import { RIVET_VERSION } from '../../config/telemetry';
import { checkPublishedCliVersion } from '../../install/automaticCliUpdate';
import { errorResult, okResult, type CliCommandResult } from '../envelope';
import { isNewerVersion } from '../serverVersion';
import { isCommandResult, parseCommandContext } from './shared';

const COMMAND = 'version';

export const handleVersion = async (
  args: string[],
): Promise<CliCommandResult> => {
  const context = parseCommandContext(COMMAND, args);
  if (isCommandResult(context)) return context;
  if (
    context.flags.positionals.length !== 1 ||
    context.flags.positionals[0] !== 'status'
  ) {
    return errorResult(COMMAND, 'USAGE_ERROR', 'Usage: rivet version status');
  }

  const published = await checkPublishedCliVersion();
  if (!published.ok) {
    return errorResult(
      COMMAND,
      'OPERATION_FAILED',
      `Could not check the latest published Rivet version; installed version is v${RIVET_VERSION}.`,
      { installedVersion: RIVET_VERSION, reason: published.reason },
    );
  }
  return okResult(COMMAND, {
    installedVersion: RIVET_VERSION,
    publishedVersion: published.version,
    isUpdateAvailable: isNewerVersion(published.version, RIVET_VERSION),
  });
};
